/*
 * getCore — VENDORIZADO Alpha Compare (offline / Chromium 88 do CEP).
 *
 * O painel roda no CEP (Chromium 88), que NAO tem wasm-SIMD por padrao. Para
 * enviar um unico core (economia de ~8-16MB) e ter comportamento deterministico
 * tanto no painel quanto no harness Node de teste, este getCore SEMPRE carrega o
 * core NAO-SIMD "full" (tesseract-core), que suporta o motor LSTM (oem 1) via
 * parametro. Assim nao dependemos da deteccao de SIMD nem das variantes -simd/
 * -lstm que foram propositalmente removidas do pacote embutido.
 */
let TesseractCore = null;

module.exports = async (oem, _, res) => {
  if (TesseractCore === null) {
    res.progress({ status: 'loading tesseract core', progress: 0 });
    TesseractCore = require('tesseract.js-core/tesseract-core');
    res.progress({ status: 'loading tesseract core', progress: 1 });
  }
  return TesseractCore;
};
